local tsv = import("tsv", {rootdir = os.scriptdir()})

local function render(names)
    local out = {'#import <Foundation/Foundation.h>', '#import <Security/Security.h>', '',
        '// GENERATED by gen-security-cases.lua from the names list - a hand-copied list goes stale, and',
        '// fifteen TLS functions were once decided as implemented because their REASON read like a later',
        '// arrival. The list is the port own: these names are the SDK own, in both builds.', ''}
    for _, n in ipairs(names) do
        out[#out + 1] = 'extern const CFStringRef ' .. n .. ';'
    end
    out[#out + 1] = ''
    out[#out + 1] = 'void security_run(void (*record)(const char *, const char *))'
    out[#out + 1] = '{'
    for _, n in ipairs(names) do
        out[#out + 1] = '    {'
        out[#out + 1] = '        NSString *value = (__bridge NSString *)(' .. n .. ');'
        out[#out + 1] = '        const char *utf8 = value.UTF8String;'
        out[#out + 1] = '        record("' .. n .. '", utf8 ? utf8 : "(unreadable)");'
        out[#out + 1] = '    }'
    end
    out[#out + 1] = '}'
    return table.concat(out, "\n") .. "\n"
end

function main(...)
    local dir = os.scriptdir()
    local cases_path = dir .. "/cases.m"

    local names = {}
    for _, line in ipairs(tsv.text_lines(tsv.read_text(dir .. "/algorithms.txt"))) do
        local s = tsv.strip(line)
        if s ~= "" then
            names[#names + 1] = s
        end
    end
    table.sort(names, tsv.byte_less)
    local text = render(names)

    local check = false
    for _, a in ipairs({...}) do
        if a == "--check" then
            check = true
        end
    end
    if check then
        if tsv.read_text(cases_path) == text then
            print("cases.m is what the list says: " .. #names .. " constants")
            os.exit(0)
        end
        print("FAIL cases.m is not what the list says")
        os.exit(1)
    end
    local handle = assert(io.open(cases_path, "wb"))
    handle:write(text)
    handle:close()
    print("cases.m written: " .. #names .. " constants")
    os.exit(0)
end
